import java.util.Scanner;

public class Main {
    public static long computeGCD(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    public static long computeLCM(long a, long b) {
        return a / computeGCD(a, b) * b;
    }

    static class Fraction {
        long num;
        long den;

        Fraction(long num, long den) {
            this.num = num;
            this.den = den;
        }
    }

    public static Fraction absolute(Fraction f) {
        return new Fraction(Math.abs(f.num), f.den);
    }

    public static int compareFractions(Fraction a, Fraction b) {
        long l = computeLCM(a.den, b.den);
        long na = a.num * (l / a.den);
        long nb = b.num * (l / b.den);
        if (na == nb) return 0;
        return (na < nb) ? -1 : 1;
    }

    public static Fraction subtractFractions(Fraction a, Fraction b) {
        long l = computeLCM(a.den, b.den);
        long na = a.num * (l / a.den);
        long nb = b.num * (l / b.den);
        long res_num = na - nb;
        long g = computeGCD(Math.abs(res_num), l);
        return new Fraction(res_num / g, l / g);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();
        sc.close();

        long g = computeGCD(x, y);
        x /= g;
        y /= g;
        Fraction xy = new Fraction(x, y);
        Fraction bestDiff = new Fraction(1000000000000L, 1);
        Fraction bestValue = new Fraction(0, 0);

        for (long b = 1; b <= n; b++) {
            long l = 0, r = 1000000;
            double maxv = ((double) x) / y + ((double) bestDiff.num) / bestDiff.den + 2;
            maxv *= b;
            r = (long) maxv;

            while (l <= r) {
                long mid = l + (r - l) / 2;
                Fraction candidate = new Fraction(mid, b);
                Fraction diff = absolute(subtractFractions(xy, candidate));
                int cmp = compareFractions(diff, bestDiff);
                if (cmp == 0) {
                    if (candidate.den < bestValue.den)
                        bestValue = candidate;
                    else if (candidate.den == bestValue.den && candidate.num < bestValue.num)
                        bestValue = candidate;
                } else if (cmp < 0) {
                    bestDiff = diff;
                    bestValue = candidate;
                }
                if (compareFractions(candidate, xy) < 0)
                    l = mid + 1;
                else
                    r = mid - 1;
            }
        }
        System.out.println(bestValue.num + "/" + bestValue.den);
    }
}
